import { html , render , WebComponent , customElement , attr , attrState , state, css, ViewTemplate, ViewContext, asyncAppend, repeat, children } from '@lithium-framework/core';
import '@lithium-framework/router-element';
import 'unofficial-pf-v5-wc';
import 'unofficial-pf-v5-wc-icons';
import '../../components';

@customElement({
  name: 'table-rows-infos',
  template: html`${(tableInfos: TableInfos) => {
    return html`
      <div class="table-infos">
        ${asyncAppend(tableInfos.preloadData(), (result) => {
          console.log(result);
          return html`
            ${repeat(
              result,
              html`${(cour) => {
                console.log(cour)
                return html`<row-infos></row-infos>`
              }}`
            )}`;
        })}
      </div>
    `;
  }}`,
  styles: [
    css`
      /* Ajoute tes styles ici */
    `,
  ],
})
export class TableInfos extends WebComponent {
  async preloadData(): Promise<any[]> {
    try {
        const response = await fetch('http://localhost:3000/cours/', {
            method: 'GET',
            headers: { 'Content-Type': 'application/json' },
        });
    
        if (!response.ok) {
            throw new Error('Erreur serveur.');
        }
    
        const data = await response.json();
        return data.length > 0 ? data : [];
    } catch (error) {
        console.error('Erreur lors de la requête fetch:', error);
        return [];
    }
  }
}



@customElement({
  name: 'row-infos',
  template: html`${(rowInfos: rowInfos) => {
    return html`
        <div class="row">
          <div class="type-de-cours"></div>
          <div class="date"></div>
          <div class="heure-debut"></div>
          <div class="heure-fin"></div>
          <pf-button>Réservez</pf-button>
          ${rowInfos.isAdmin === true
            ? html`
                <div class="icon-down">
                  <div class="icon">
                    <pf-icons-chevron-down></pf-icons-chevron-down>
                  </div>
                </div>
              `
            : html``}
        </div>
        <div class="participants">

        </div>`;
  }}`,
  styles: [
    css`
      /* Ajoute tes styles ici */
    `,
  ],
})
export class rowInfos extends WebComponent {
  data: any[] = [];
  particpants: any[] = [];

  @state() isAdmin: boolean = null;
  @state() isVisible: boolean = null;

  @attr visible: "true" | "false" | null = null;

  attributeChangedCallback(name: string, oldValue: string | null, newValue: string | null): void {
    if (name === "visible") {
        this.isVisible = newValue === "true";
    }
    super.attributeChangedCallback(name, oldValue, newValue);
  }
    // Méthode pour récupérer le rôle et affecter isAdmin
    getRole() {
      const userDataString = localStorage.getItem('userData');
      if (!userDataString) {
        throw new Error('Utilisateur non connecté. Aucune donnée dans localStorage.');
      }
  
      const userData = JSON.parse(userDataString);
      console.log('Données utilisateur récupérées:', userData);
  
      // Récupérer le rôle de l'utilisateur
      const userRole = userData.role;
      console.log('Rôle de l\'utilisateur:', userRole);
  
      // Vérifier si le rôle est 'administrator' ou 'super-administrator' et mettre à jour isAdmin
      if (userRole === 'administrator' || userRole === 'super-administrator') {
        this.isAdmin = true;
      } else {
        this.isAdmin = false;
      }
  
      console.log('Est-ce un administrateur ? ', this.isAdmin);
    }

  async loadDataParticipants(cour){
    try {
      const courId = cour.id;
      console.log(courId);
  
      const response = await fetch('http://localhost:3000/cours/inscription/participants', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ cours_id: courId })
      });
  
      if (!response.ok) {
        throw new Error('Erreur serveur.');
      }
  
      const data = await response.json();
  
      // Si la réponse est un tableau, retourne-le directement
      if (Array.isArray(data.participants)) {
        //console.log(data.participants);
        return data.participants;
      } else {
        console.log("Réponse vide ou mal formatée.");
        return [];
      }
  
    } catch (error) {
      console.error('Erreur lors de la requête fetch:', error);
      return [];
    }
  }

  displayParticipants(cour) {
    this.isVisible = !this.isVisible;
    this.visible = this.isVisible ? "true" : "false";
  }

  async register(cour) {
    try {
        const userDataString = localStorage.getItem('userData');
        if (!userDataString) {
            throw new Error('Utilisateur non connecté. Aucune donnée dans localStorage.');
        }

        const userData = JSON.parse(userDataString);
        console.log('Données utilisateur récupérées:', userData);

        const inscriptionData = {
            user: userData, 
            cours: cour
        };
        console.log(inscriptionData);

        // Faire la requête fetch
        const response = await fetch('http://localhost:3000/cours/inscription', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(inscriptionData)
        });

        // Vérifier si la requête a réussi
        if (!response.ok) {
            throw new Error('Erreur serveur.');
        }

        // Récupérer les données JSON de la réponse
        const data = await response.json();
        console.log(data);

        // Vérifier si la réponse contient un message et gérer en conséquence
        if (data && data.message) {
          console.log(data.message);  // Affiche le message du serveur
          if (data.message === "Inscription réussie !") {
              console.log("Bien inscrit au cours");
          } else {
              console.log("Pas d'inscription ou réponse inattendue.");
          }
        } else {
            console.log("Réponse vide ou mal formatée.");
        }

    } catch (error) {
        console.error('Erreur lors de la requête fetch:', error);
        return [];
    }
  }
  
  

  formatDateFromISO(isoDateString: string): string {
    const date = new Date(isoDateString);
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  }

  convertToISODate(dateString: string): string {
    const [year, month, day] = dateString.split('-');
    return new Date(`${year}-${month}-${day}T00:00:00Z`).toISOString();
  }

}



